// ---------------------------------------------------------------
// Indexa os clientes JA cadastrados no dashboard, para nao duplicar.
// Recebe um item por pagina (a paginacao do node anterior).
// ---------------------------------------------------------------
const paginas = $input.all();

const docs = new Set();
const telsSufixo = new Set();
let total = 0;

for (const p of paginas) {
  const body = p.json ?? {};
  const arr = Array.isArray(body.data) ? body.data : [];
  for (const c of arr) {
    total++;
    const d = String(c.cnpjCpf ?? '').replace(/\D/g, '');
    if (d) docs.add(d);
    const t = String(c.contatoWhatsapp ?? '').replace(/\D/g, '');
    // sufixo de 10 digitos (DDD + numero sem o 9) - tolera variacao de +55 e do 9o digito
    if (t.length >= 10) telsSufixo.add(t.slice(-10));
  }
}

// Se o indice vier vazio, o cruzamento nao funciona e o workflow duplicaria
// todo mundo. Melhor parar aqui mostrando o que a API respondeu de fato.
if (total === 0) {
  const amostra = JSON.stringify(paginas[0]?.json ?? null).slice(0, 400);
  throw new Error('GET /api/clientes nao devolveu nenhum cliente - abortando para nao duplicar. Resposta da 1a pagina: ' + amostra);
}

console.log('[Existentes] ' + total + ' cliente(s) no dashboard | ' +
            docs.size + ' com CNPJ/CPF | ' + telsSufixo.size + ' telefone(s) indexado(s)');

return [{
  json: {
    total_existentes: total,
    docs: Array.from(docs),
    tels_sufixo: Array.from(telsSufixo),
  },
}];

// ---------------------------------------------------------------
// Filtra os contatos do Bling que interessam.
// ---------------------------------------------------------------

// Vira true se voce tambem quiser puxar pessoa fisica (CPF, 11 digitos).
const INCLUIR_CPF = false;

// Blacklist, nao whitelist: so descartamos o que sabemos que nao serve.
// Situacao no Bling: 'A' = Ativo, 'I' = Inativo, 'E' = Excluido.
// Qualquer outra situacao (inclusive nao mapeada ou vazia) passa.
const SITUACOES_RECUSADAS = ['I', 'E'];

const entrada = $input.all();
const saida = [];
let semDoc = 0, pessoaFisica = 0, recusados = 0;

for (const item of entrada) {
  const c = item.json ?? {};
  const doc = String(c.numeroDocumento ?? '').replace(/\D/g, '');

  if (!doc) { semDoc++; continue; }

  const ehCnpj = doc.length === 14;
  const ehCpf = doc.length === 11;

  if (!ehCnpj && !ehCpf) { semDoc++; continue; }
  if (ehCpf && !INCLUIR_CPF) { pessoaFisica++; continue; }

  const situacao = c.situacao ?? null;
  if (situacao && SITUACOES_RECUSADAS.includes(String(situacao).toUpperCase())) { recusados++; continue; }

  saida.push({ json: { id: c.id, nome: c.nome ?? null, numeroDocumento: doc, situacao } });
}

console.log('[Bling] recebidos=' + entrada.length +
            ' | aprovados=' + saida.length +
            ' | sem doc valido=' + semDoc +
            ' | pessoa fisica ignorada=' + pessoaFisica +
            ' | inativos/excluidos=' + recusados);

return saida;

// ---------------------------------------------------------------
// Cruza os contatos do Bling com quem ja existe e monta APENAS os novos,
// no formato exato que o POST /api/clientes espera.
// ---------------------------------------------------------------

// O schema exige diaDisparo e o Bling nao tem esse dado.
const DIA_PADRAO = 'SEGUNDA';
// Tag para identificar depois quem veio dessa importacao.
const TAGS = ['bling'];

const idx = $('Indexa existentes').first().json;
const docsExistentes = new Set(idx.docs ?? []);
const telsExistentes = new Set(idx.tels_sufixo ?? []);

// $input.first() em vez de $json: funciona nos dois modos do Code node.
const detalhados = $input.first().json.contatos_detalhados ?? [];

// Transforma o objeto de erro do n8n em texto legivel.
// (E daqui que sai o famoso "[object Object]" quando se concatena direto.)
function textoDoErro(e) {
  if (e == null) return 'erro desconhecido';
  if (typeof e === 'string') return e;
  const partes = [];
  if (e.message) partes.push(String(e.message));
  if (e.description) partes.push(String(e.description));
  if (e.httpCode) partes.push('HTTP ' + e.httpCode);
  return partes.length ? partes.join(' | ') : JSON.stringify(e).slice(0, 300);
}

// Telefone no padrao do banco: 55 + DDD + numero (so digitos).
function normalizarTelefone(...candidatos) {
  for (const raw of candidatos) {
    if (!raw) continue;
    let d = String(raw).replace(/\D/g, '');
    if (!d) continue;
    d = d.replace(/^0+/, '');
    let local = d;
    if (local.length > 11 && local.startsWith('55')) local = local.slice(2);
    if (local.length === 10 || local.length === 11) return '55' + local;
  }
  return null;
}

// Chute de segmento pelo nome. E so um palpite - revise no dashboard depois.
function chutarSegmento(nome) {
  const n = (nome || '').toLowerCase();
  if (/hotel|pousada|resort|hostel|motel/.test(n)) return 'HOTELARIA';
  if (/academia|fitness|gym|crossfit|pilates/.test(n)) return 'ACADEMIA';
  if (/evento|buffet|bufe|recep[cç]|festa|salao/.test(n)) return 'EVENTOS';
  if (/distribuidor|atacad|represent|comercial|mercadinho|mercado|supermerc/.test(n)) return 'DISTRIBUIDOR';
  if (/franquia|franchis/.test(n)) return 'FRANQUIA';
  if (/restaurante|lanchonete|pizza|churrasc|refei|self.?service|espetinho|burger|hamburg|sushi|padaria|tapiocaria|creperia|acai|sorvet|bar\b|cafe|bistro|comida|cozinha|grill|espeto/.test(n)) return 'RESTAURANTE';
  return 'OUTRO';
}

const novos = [];
const jaExistiam = [];
const semTelefone = [];
const falhaNoDetalhe = [];
const docsNoLote = new Set();

for (const item of detalhados) {
  // Se o GET de detalhe falhou, o item vem como { error: ... } em vez de { data: ... }
  if (item && item.data === undefined && item.error !== undefined) {
    falhaNoDetalhe.push(textoDoErro(item.error));
    continue;
  }

  // O HTTP de detalhe responde { data: { ...contato } }
  const c = item?.data ?? item ?? {};
  const geral = c?.endereco?.geral ?? {};

  const doc = String(c.numeroDocumento ?? '').replace(/\D/g, '');
  const empresa = (c.nome ?? '').trim();
  if (!empresa || !doc) continue;

  const tel = normalizarTelefone(c.celular, c.telefone);

  if (!tel) { semTelefone.push(empresa + ' (' + doc + ')'); continue; }
  if (docsExistentes.has(doc)) { jaExistiam.push(empresa + ' [CNPJ]'); continue; }
  if (telsExistentes.has(tel.slice(-10))) { jaExistiam.push(empresa + ' [telefone]'); continue; }
  if (docsNoLote.has(doc)) { jaExistiam.push(empresa + ' [duplicado no proprio Bling]'); continue; }
  docsNoLote.add(doc);

  novos.push({
    json: {
      empresa,
      blingContatoId: c.id != null ? String(c.id) : null,
      payload: {
        empresa,
        contatoWhatsapp: tel,
        segmento: chutarSegmento(empresa),
        diaDisparo: DIA_PADRAO,
        cidade: (geral.municipio ?? '').trim() || null,
        uf: (geral.uf ?? '').trim().toUpperCase() || null,
        cnpjCpf: doc,
        tags: TAGS,
      },
    },
  });
}

console.log('[Novos] a criar=' + novos.length +
            ' | ja existiam=' + jaExistiam.length +
            ' | sem telefone=' + semTelefone.length +
            ' | falha no detalhe=' + falhaNoDetalhe.length);
if (jaExistiam.length) console.log('[Ja existiam] ' + jaExistiam.join(' ; '));
if (semTelefone.length) console.log('[Sem telefone - NAO importados] ' + semTelefone.join(' ; '));
if (falhaNoDetalhe.length) console.log('[Falha no GET de detalhe] ' + falhaNoDetalhe.join(' ; '));

// Se retornar vazio, os nodes seguintes nao rodam: significa que nao ha nada novo.
return novos;

// ---------------------------------------------------------------
// Resumo final do que foi gravado no dashboard.
//
// O node de POST esta com "Full Response" + "Never Error", entao cada item
// chega como { statusCode, headers, body } inclusive quando a API devolve
// 4xx/5xx. Assim conseguimos ler a mensagem real ({"error":"..."}) em vez do
// "[object Object]" que aparece quando se concatena o objeto de erro do n8n.
// ---------------------------------------------------------------
const respostas = $input.all();
const enviados = $('Monta novos clientes').all();

function textoDoErro(json) {
  // Erro de transporte do proprio n8n (timeout, DNS, credencial...)
  if (json?.error !== undefined) {
    const e = json.error;
    if (typeof e === 'string') return e;
    const partes = [];
    if (e?.message) partes.push(String(e.message));
    if (e?.description) partes.push(String(e.description));
    if (e?.httpCode) partes.push('HTTP ' + e.httpCode);
    return partes.length ? partes.join(' | ') : JSON.stringify(e).slice(0, 300);
  }
  // Erro devolvido pela API do dashboard
  const corpo = json?.body;
  if (corpo && typeof corpo === 'object') {
    if (corpo.error) return String(corpo.error);
    return JSON.stringify(corpo).slice(0, 300);
  }
  if (typeof corpo === 'string') return corpo.slice(0, 300);
  return JSON.stringify(json ?? null).slice(0, 300);
}

const criados = [];
const falhas = [];

for (let i = 0; i < respostas.length; i++) {
  const json = respostas[i].json ?? {};
  const nome = enviados[i]?.json?.empresa ?? '(desconhecido)';
  const status = json.statusCode ?? null;
  const corpo = json.body ?? json;

  const ok = json.error === undefined &&
             (status != null ? status >= 200 && status < 300 : corpo?.id != null);

  if (!ok) {
    falhas.push({ empresa: nome, status, erro: textoDoErro(json) });
  } else {
    criados.push({ id: corpo.id, empresa: corpo.empresa ?? nome, cnpjCpf: corpo.cnpjCpf ?? null });
  }
}

console.log('[Resultado] criados=' + criados.length + ' | falhas=' + falhas.length);
for (const f of falhas) {
  console.log('[Falha] ' + f.empresa + ' -> HTTP ' + f.status + ' - ' + f.erro);
}

return [{ json: { total_criados: criados.length, total_falhas: falhas.length, criados, falhas } }];
